import {outingPack} from './outing_pack.js';
export function lifePack(){const d=JSON.parse(JSON.stringify(outingPack()).replaceAll('outingproof','lifeproof'));d.simulation.commands.push({id:'lifeproof.fatal',revision:1,label:'Choose marked lethal trial',description:'This optional synthetic route causes true death. Export or archive this independent life afterwards.',worldId:d.world.id,location:'lifeproof.room',group:'structured_local',actorId:'player',audience:['$actor'],duration:0,costs:[],effects:[{type:'life',status:'dead',lethal:true,reason:'Synthetic local consequence.'}]});return d;}
